// NV-199 (2026-10-25): PO direct print-dictionary submission (Ia/Ua pronoun
// paradigm) + PO ruling "rice is there = Mi donga". Not native quotes.
// Existential `there is X` / `X is there` -> `X donga` (same shape as attested
// "...guang donga" in corrections.json). Unattested paradigm cells (Uachi,
// Uachipak, Uanoni, Uantok, Iakai) are NOT generated by inference.
import test from 'node:test';
import assert from 'node:assert/strict';
import { translate } from '../../src/translationEngine.js';
const lc = async (en) => (await translate(en)).garo.toLowerCase().replace(/[.!?]$/, '');

for (const [en, garo] of [
  ['from here', 'ianoni'], ['this side', 'iachipak'], ['on this side', 'iachipak'],
  ['this much', 'iantok'], ['only this much', 'iantok'],
  ['by them', 'uamangchi'], ['herewith', 'iachi'], ['hereby', 'iachi'],
  ['to this place', 'iachi'], ['here it is', 'iake'],
  ['rice is there', 'mi donga'], ['there is rice', 'mi donga'], ['the rice is there', 'mi donga'],
]) test(`NV-199: ${en}`, async () => assert.equal(await lc(en), garo));

test('NV-199: unchanged bases', async () => {
  assert.equal(await lc('there'), 'uano');
  assert.equal(await lc('here'), 'iano');
  assert.equal(await lc('them'), 'uamangko'); // NV-202: accusative `uamangko` (Project Owner relay); `uamangna` is the dative (to/for them)
  assert.equal((await translate('there\'s a spider under your bed')).garo, 'Aiwa nang·ni palang ning·o guang donga.');
});
test('NV-199: no inferred cells', async () => {
  for (const en of ['from there', 'that side', 'that much']) {
    const g = await lc(en);
    assert.ok(!/^(uanoni|uachi|uachipak|uantok)$/.test(g), `${en} -> ${g}`);
  }
});
